/** Owner-private manual review. No OCR call and no financial posting. */
session_start();require_once __DIR__.'/db_connect.php';require_once __DIR__.'/includes/require_role.php';require_once __DIR__.'/includes/receipt_ocr.php';require_once __DIR__.'/includes/layout.php';require_login();header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');
$error='';$model=null;$result=null;$uid=(int)($_SESSION['UserID']??0);
