        if((int)($_SERVER['CONTENT_LENGTH']??0)>180000)throw new JournalProblem('The item review is too large.',413);
        $raw=file_get_contents('php://input',false,null,0,180001);if($raw===false||strlen($raw)>180000)throw new JournalProblem('The item review is too large.',413);try{$r=json_decode($raw,true,32,JSON_THROW_ON_ERROR);}catch(JsonException $e){throw new JournalProblem('Check the review form.',400);}if(!is_array($r)||array_is_list($r))throw new JournalProblem('Check the review form.',400);$result=item_review_confirm($pdo,$uid,$r);
        header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>true,'result'=>$result],JSON_THROW_ON_ERROR);exit;
    }
    $rid=reporting_id($_GET['receipt_id']??null,'image');$draft=reporting_id($_GET['draft_id']??null,'draft',true);$journal=reporting_id($_GET['journal_id']??null,'transaction',true);if($journal!==null&&$draft!==null)throw new JournalProblem('Choose one evidence context.',400);
    $model=accounting_read($pdo,function()use($pdo,$uid,$rid,$draft,$journal){if($journal!==null)return item_review_posted_model($pdo,$uid,$rid,$journal);$context=item_review_context($pdo,$uid,$rid,$draft);$current=item_review_current($pdo,$rid,$context['key']);$attempt=receipt_latest_attempt($pdo,$rid);$suggestions=$attempt&&$attempt['normalized_json']!==null?json_decode($attempt['normalized_json'],true,32,JSON_THROW_ON_ERROR):[];$data=$current['data']??['merchant'=>$suggestions['merchant']??'','reference'=>$suggestions['reference']??'','date'=>$suggestions['transaction_date']??'','currency'=>($suggestions['currency']??'')==='PHP'?'PHP':'','declared_total'=>$suggestions['total_amount']??'','items'=>$suggestions['items']??[],'complete'=>false,'incomplete_reason'=>$suggestions['itemization_note']??''];$return='ocr_expense.php?receipt='.$rid;if($draft!==null){$d=workspace_draft($pdo,$uid,$draft);$return=(int)$d['payload_version']===4?'journal_correction.php?draft_id='.$draft.'&journal_id='.$d['correction_target_journal_id']:($d['workflow_kind']!=='ordinary'?'cash_advance_entry.php?draft_id='.$draft:($d['source_book']==='CDB'?'cash_disbursement.php':($d['source_book']==='CRB'?'cash_receipt.php':'general_journal.php')).'?draft_id='.$draft);}
        return ['read_only'=>false,'receipt_id'=>$rid,'draft_id'=>$draft,'revision'=>(int)($current['revision_number']??0),'name'=>$context['image']['Original_Filename'],'image_url'=>'receipt_attachment.php?receipt_id='.$rid.($draft!==null&&$context['image']['JournalEntryID']!==null?'&draft_id='.$draft:''),'return_url'=>$return,'data'=>$data];});
}catch(Throwable $e){$status=($e instanceof JournalProblem||$e instanceof ReportingProblem)?$e->status:503;http_response_code($status);$error=$status===503?'Evidence review is temporarily unavailable. No financial record changed.':$e->getMessage();if($_SERVER['REQUEST_METHOD']==='POST'){header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>false,'error'=>$error]);exit;}}
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');layout_begin('Review image details','ocr_expense',[],'<link rel="stylesheet" href="assets/css/evidence_item_review.css?v='.filemtime(__DIR__.'/assets/css/evidence_item_review.css').'">');
