<?php if($model):?><p id="ir-status" role="status"><?= $model['read_only']?'Recorded item review '.$model['revision'].' - read only':($model['revision']?'Confirmed review '.$model['revision'].'. New changes need a new confirmation.':'Not confirmed yet. Automatic suggestions need your review.') ?></p><a href="<?= $e($model['return_url']) ?>">Back to transaction</a><div class="ir-grid"><section><h2>Original image</h2><p><?= $e($model['name']) ?></p><a href="<?= $e($model['image_url']) ?>" target="_blank" rel="noopener">Open original at full size</a><img src="<?= $e($model['image_url']) ?>" alt="Original supporting document"></section><?php if($model['read_only']):?><section id="ir-recorded"><h2>Recorded item details</h2><p>Confirmed by <?= $e($model['confirmed_by']) ?> at <?= $e($model['confirmed_at']) ?> UTC. Corrections preserve this original review.</p><dl><?php foreach(['merchant'=>'Merchant','reference'=>'Reference','date'=>'Document date','currency'=>'Currency','declared_total'=>'Document total','item_total'=>'Item total','incomplete_reason'=>'Itemization note'] as $key=>$label):?><dt><strong><?= $e($label) ?></strong></dt><dd><?= $e($model['data'][$key]) ?></dd><?php endforeach;?></dl><p><?= $model['data']['complete']?'Complete itemization':'Incomplete itemization' ?>. Journal monetary coverage remains separate.</p><div class="ir-table"><table><thead><tr><th>Description</th><th>Quantity</th><th>Amount (PHP)</th></tr></thead><tbody><?php foreach($model['data']['items'] as $item):?><tr><td><?= $e($item['description']) ?></td><td><?= $e($item['quantity']) ?></td><td><?= $e($item['amount']) ?></td></tr><?php endforeach;?></tbody></table></div></section><?php else:?><form id="ir-form"><h2>Verified details</h2><p>Confirm the document total here. Accepted/excluded amounts and journal allocations are reviewed in the transaction form.</p>
<?php foreach(['merchant'=>'Merchant','reference'=>'Reference','date'=>'Document date','declared_total'=>'Document total (PHP)'] as $key=>$label):?><label><?= $e($label) ?><input id="ir-<?= $e($key) ?>" name="<?= $e($key) ?>" type="<?= $key==='date'?'date':'text' ?>" maxlength="<?= $key==='merchant'?255:($key==='reference'?100:32) ?>" value="<?= $e($model['data'][$key]) ?>"<?= $key==='declared_total'?' required inputmode="decimal"':'' ?>></label><?php endforeach;?><label>Printed currency<select id="ir-currency" required><option value="">Confirm printed currency</option><option value="PHP"<?= $model['data']['currency']==='PHP'?' selected':'' ?>>PHP</option></select></label><p>Only verified PHP documents are supported here. No currency conversion is performed.</p>
