<label><input type="checkbox" id="ir-complete"<?= $model['data']['complete']?' checked':'' ?>>All items are included and add exactly to the document total</label><label>Missing items, tax, discounts or differences<textarea id="ir-reason" maxlength="1000"><?= $e($model['data']['incomplete_reason']) ?></textarea></label><label><input type="checkbox" id="ir-confirm" required>I inspected the original image and confirmed these details</label><button id="ir-save" type="submit">Confirm and save details</button><button id="ir-retry" type="button" hidden>Check original save result</button><p>Changing these details requires a fresh journal Review. Nothing is recorded as a financial transaction here.</p></form><?php endif;?></div>
